export const GRADES=[
 {name:'Thường',color:'Trắng',hex:'#e5e7eb',bg:'#40464f',power:1},
 {name:'Khá hiếm',color:'Xanh lá',hex:'#78d98a',bg:'#20563a',power:1.8},
 {name:'Hiếm',color:'Xanh lam',hex:'#75b8ff',bg:'#234f80',power:3.1},
 {name:'Sử thi',color:'Đỏ',hex:'#ff8b85',bg:'#803438',power:5.2},
 {name:'Huyền thoại',color:'Vàng',hex:'#ffdb75',bg:'#806128',power:8.5}
];
export const MATERIALS={ore:{name:'Thanh Thạch',icon:'◆',source:'Đào khoáng'},herb:{name:'Linh thảo',icon:'❧',source:'Hái thuốc'},energy:{name:'Linh khí',icon:'✧',source:'Hấp thu'},essence:{name:'Linh phách',icon:'◉',source:'Săn quái / boss'},cloth:{name:'Linh bì',icon:'▧',source:'Hái thuốc'},steel:{name:'Huyền thiết',icon:'⚒',source:'Đào khoáng'},gem:{name:'Ngọc tinh',icon:'◇',source:'Hấp thu'},feather:{name:'Thiên vũ',icon:'羽',source:'Hấp thu / boss'},stone:{name:'Đá cường hóa',icon:'⬡',source:'Luyện 2 Thanh Thạch + 1 linh khí cùng màu'}};
export const SLOTS={
 helmet:{name:'Mũ',group:'armor',icon:'♜',base:{hp:12,def:1}},chest:{name:'Áo giáp',group:'armor',icon:'▣',base:{hp:24,def:2}},pants:{name:'Quần',group:'armor',icon:'▤',base:{hp:18,def:1}},gloves:{name:'Găng tay',group:'armor',icon:'✋',base:{hp:10,atk:2}},boots:{name:'Giày',group:'armor',icon:'♟',base:{hp:12,def:1}},mainhand:{name:'Vũ khí chính',group:'weapon',icon:'⚔',base:{atk:10}},offhand:{name:'Vũ khí phụ',group:'weapon',icon:'†',base:{atk:5,def:1}},necklace:{name:'Vòng cổ',group:'accessory',icon:'◇',base:{hp:15,mp:8}},bracelet:{name:'Vòng tay',group:'accessory',icon:'◎',base:{atk:3,def:1}},ring:{name:'Nhẫn',group:'accessory',icon:'◉',base:{atk:4,mp:8}},wings:{name:'Cánh',group:'wings',icon:'羽',base:{atk:4,hp:20,mp:10}}
};
export const RECIPES={armor:{name:'Giáp',materials:{cloth:6,ore:3,herb:2}},weapon:{name:'Vũ khí',materials:{steel:8,ore:4,energy:2}},accessory:{name:'Phụ kiện',materials:{gem:6,energy:4,herb:2}},wings:{name:'Cánh',materials:{feather:8,gem:4,energy:6}}};
export const PETS={fox:{name:'Hỏa hồ',shape:'fox',grade:0,icon:'狐',desc:'Linh hỏa tấn công mỗi 3 giây.',bonus:{atk:4},unlock:0},crane:{name:'Thanh hạc',shape:'crane',grade:0,icon:'鶴',desc:'Hồi sinh lực định kỳ.',bonus:{hp:18},unlock:0},turtle:{name:'Huyền quy',shape:'turtle',grade:1,icon:'龜',desc:'Mai linh thạch tăng phòng thủ.',bonus:{def:4},unlock:1},wolf:{name:'Ngân lang',shape:'wolf',grade:1,icon:'狼',desc:'Cắn mục tiêu gần, tăng công.',bonus:{atk:7},unlock:1},deer:{name:'Bạch lộc',shape:'deer',grade:2,icon:'鹿',desc:'Hồi phục và tăng linh lực.',bonus:{hp:25,mp:12},unlock:2},phoenix:{name:'Xích phượng',shape:'phoenix',grade:3,icon:'鳳',desc:'Hỏa vũ gây sát thương định kỳ.',bonus:{atk:12,mp:15},unlock:3},dragon:{name:'Kim long',shape:'dragon',grade:4,icon:'龍',desc:'Long tức công kích, tăng công thủ.',bonus:{atk:18,def:5},unlock:4},tiger:{name:'Bạch hổ',shape:'tiger',grade:2,icon:'虎',desc:'Tấn công mạnh và bảo vệ chủ nhân.',bonus:{atk:9,def:3},unlock:2}};
export const emptyMaterials=()=>Object.fromEntries(Object.keys(MATERIALS).map(k=>[k,GRADES.map(()=>({bound:0,trade:0}))]));
export function ensureEconomy(s){if(!s.materials){s.materials=emptyMaterials();for(const k of ['ore','herb','energy','essence'])s.materials[k][0].bound=s[k]||0;}s.items??=[];s.equipped??={};s.nextItemId??=1;s.materialPreference??='bound-first';s.petLevels??={...s.spirits};for(const k of Object.keys(PETS))s.petLevels[k]??=0;return s;}
export const amount=(s,k,g)=>{const m=s.materials?.[k]?.[g];return m?m.bound+m.trade:0;};
export function addMaterial(s,k,g,n=1,trade=false){if(!MATERIALS[k]||!Number.isInteger(g)||!GRADES[g]||!Number.isInteger(n)||n<0)throw Error('Nguyên liệu không hợp lệ');s.materials[k][g][trade?'trade':'bound']+=n;syncLegacy(s);}
export function syncLegacy(s){for(const k of ['ore','herb','energy','essence'])s[k]=amount(s,k,0);}
export function canMaterials(s,recipe,g){return Object.entries(recipe).every(([k,n])=>amount(s,k,g)>=n);}
export function spendMaterials(s,recipe,g){if(!canMaterials(s,recipe,g))return false;for(const [k,n]of Object.entries(recipe)){let left=n,m=s.materials[k][g];for(const t of (s.materialPreference==='trade-first'?['trade','bound']:['bound','trade'])){let use=Math.min(m[t],left);m[t]-=use;left-=use;}}syncLegacy(s);return true;}
export function itemStats(item){const out={hp:0,mp:0,atk:0,def:0};const m=GRADES[item.grade].power*(1+(item.tier-1)*.4)*(1+item.enhance*.08);for(const [k,v]of Object.entries(SLOTS[item.slot].base))out[k]=Math.round(v*m);return out;}
export function equipmentStats(s){let out={hp:0,mp:0,atk:0,def:0};for(const id of Object.values(s.equipped||{})){const it=s.items?.find(x=>x.id===id);if(it)for(const [k,v]of Object.entries(itemStats(it)))out[k]+=v;}return out;}
export function petStats(s){const p=PETS[s.spirit],lv=s.petLevels?.[s.spirit]||s.spirits?.[s.spirit]||0;const out={hp:0,mp:0,atk:0,def:0};if(p)for(const[k,n]of Object.entries(p.bonus))out[k]=Math.round(n*lv*(1+(s.companions?.treasures[s.spirit]||0)*.1));return out;}
export function gearRecipe(slot,grade){if(!SLOTS[slot]||!Number.isInteger(grade)||!GRADES[grade])return null;return {gold:40*(grade+1),materials:RECIPES[SLOTS[slot].group].materials};}
export function enhancementRecipe(item){return {gold:20*(item.grade+1)*(item.enhance+1),materials:{stone:1+Math.floor(item.enhance/3)}};}
export function newItem(s,slot,grade,tier=1,enhance=0,tradable=false){const it={id:'gear-'+s.nextItemId++,slot,grade,tier,enhance,tradable,protected:false};s.items.push(it);return it;}
export function materialPlan(s,k,grade,quantity){let missing=Math.max(0,quantity-amount(s,k,grade));const rows=[{grade,need:quantity,owned:amount(s,k,grade),missing}];for(let g=grade-1;g>=0&&missing>0;g--){const need=missing*10,owned=amount(s,k,g);missing=Math.max(0,need-owned);rows.push({grade:g,need,owned,missing});}return rows;}
export function validateEconomy(s){
 if(!s.materials||Object.keys(MATERIALS).some(k=>!Array.isArray(s.materials[k])||s.materials[k].length!==5||s.materials[k].some(m=>!m||!['bound','trade'].every(t=>Number.isSafeInteger(m[t])&&m[t]>=0&&m[t]<=1e8))))throw Error('Kho nguyên liệu không hợp lệ');
 if(!Array.isArray(s.items)||s.items.length>500||new Set(s.items.map(i=>i.id)).size!==s.items.length||s.items.some(i=>!i||typeof i.id!=='string'||!/^gear-\d+$/.test(i.id)||!Object.hasOwn(SLOTS,i.slot)||!Number.isInteger(i.grade)||!GRADES[i.grade]||!Number.isInteger(i.tier)||i.tier<1||i.tier>4||!Number.isInteger(i.enhance)||i.enhance<0||i.enhance>8||typeof i.tradable!=='boolean'||typeof i.protected!=='boolean'))throw Error('Trang bị trong bản lưu không hợp lệ');
 if(!s.equipped||typeof s.equipped!=='object'||Array.isArray(s.equipped)||Object.entries(s.equipped).some(([slot,id])=>!SLOTS[slot]||!s.items.some(i=>i.id===id&&i.slot===slot)))throw Error('Trang bị đang mặc không hợp lệ');
 if(!Number.isSafeInteger(s.nextItemId)||s.nextItemId<1||s.nextItemId<=Math.max(0,...s.items.map(i=>+i.id.slice(5))))throw Error('Mã vật phẩm không hợp lệ');
 if(!s.petLevels||Object.keys(PETS).some(k=>!Number.isInteger(s.petLevels[k])||s.petLevels[k]<0||s.petLevels[k]>5)||!Object.hasOwn(PETS,s.spirit))throw Error('Pet không hợp lệ');
 if(!['bound-first','trade-first'].includes(s.materialPreference))throw Error('Thứ tự tiêu hao không hợp lệ');
}
